SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2013.YEAR, Станции2013.NUST, Станции2013.nr, Станции2013.E, Станции2013.EOTP, Станции2013.EURT, Станции2013.EUST, Станции2013.Q, Станции2013.TURT, Станции2013.TUST, Станции2013.B, Станции2013.GAZ, Доп_угли2013.gazpp, Станции2013.MAZUT, Станции2013.TORF, Станции2013.SLAN, Станции2013.PROCH, Станции2013.UGOL, Станции2013.DON, Станции2013.PODM, Станции2013.PECH, Доп_угли2013.intin, Доп_угли2013.vork, Станции2013.ARKT, Станции2013.KUZN, Доп_угли2013.kuzngd, Доп_угли2013.kuznt, Доп_угли2013.kuznss, Доп_угли2013.kuznun, Станции2013.URAL, Доп_угли2013.sver, Доп_угли2013.chel, Доп_угли2013.kizel, Станции2013.BASHK, Станции2013.KAZAH, Доп_угли2013.ekib, Доп_угли2013.maikub, Станции2013.KARAG, Станции2013.KAN, Доп_угли2013.nazar, Доп_угли2013.ibor, Доп_угли2013.berez, Доп_угли2013.per, Доп_угли2013.irbei, Доп_угли2013.kansk, Станции2013.TUNG, Доп_угли2013.jer, Доп_угли2013.karab, Станции2013.IRKUT, Доп_угли2013.azey, Доп_угли2013.mug, Доп_угли2013.cher, Станции2013.HAK, Станции2013.TUV, Станции2013.BUR, Доп_угли2013.gusin, Доп_угли2013.tugn, Доп_угли2013.okino, Станции2013.CHIT, Доп_угли2013.har, Доп_угли2013.urt, Доп_угли2013.tataur, Доп_угли2013.tarbag, Доп_угли2013.zab_kam, Станции2013.YAKUT, Доп_угли2013.neru, Доп_угли2013.zyryan, Доп_угли2013.pyak, Станции2013.AMUR, Доп_угли2013.rai, Доп_угли2013.erk, Станции2013.URG, Станции2013.USHUM, Станции2013.PRIM, Доп_угли2013.bikin, Доп_угли2013.razdol, Доп_угли2013.hankai, Станции2013.MAG, Станции2013.SAH, Станции2013.KAMCH, Станции2013.CHUKOT, Доп_угли2013.anad, Доп_угли2013.bering, Станции2013.QOTR, Станции2013.SNK, Станции2013.EWTP, Станции2013.NT, Станции2013.OBOR, Станции2013.VED, Станции2013.OBL, Станции2013.DEP, Станции2013.OES, Станции2013.ER, Станции2013.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Станции2013.BE, имена_ГК.name AS namegk, имена_БЕ.name AS namebe, Города.Name AS Town, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип
FROM (((Имена_станций LEFT JOIN Города ON Имена_станций.codegor=Города.code) INNER JOIN (Имена_областей INNER JOIN (Имена_ОЭС INNER JOIN (Станции2013 LEFT JOIN Доп_угли2013 ON (Станции2013.NUMB1120=Доп_угли2013.NUMB1120) AND (Станции2013.YEAR=Доп_угли2013.YEAR)) ON Имена_ОЭС.oes=Станции2013.OES) ON Имена_областей.OBL=Станции2013.OBL) ON Имена_станций.NUMB=Станции2013.NUMB1120) LEFT JOIN имена_ГК ON Станции2013.GK=имена_ГК.code) LEFT JOIN имена_БЕ ON Станции2013.BE=имена_БЕ.code;
